import * as THREE from 'three/webgpu';
import { Fn, uv, uniform, mix, color, smoothstep, step, vec3, float, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'gradient-cta';

  const W = 2.6, H = 0.68;
  const geometry = new THREE.PlaneGeometry(W, H, 1, 1);

  const stops = (config.visual?.colors?.gradientStops) || [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const accentHex = config.visual?.colors?.accent || '#ff2a38';

  const c0 = uniform(color(stops[0].hex));
  const c1 = uniform(color(stops[1].hex));
  const c2 = uniform(color(stops[2].hex));
  const seamAt = uniform(float(stops[1].at));
  const emissiveIntensity = uniform(float(1.6));
  const accentColor = uniform(color(accentHex));

  const material = new THREE.MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
  });

  const vUv = uv();

  const gradientNode = Fn(() => {
    const t = vUv.y;
    const lowerMix = smoothstep(0.0, seamAt, t);
    const lower = mix(c0, c1, lowerMix);
    const upperMix = smoothstep(seamAt, float(1.0), t);
    const upper = mix(c1, c2, upperMix);
    const seamHard = step(seamAt, t);
    const baseColor = mix(lower, upper, seamHard);

    // perimeter emissive band (0.015 unit wide out of W/H) - approximate via uv edge distance
    const edgeDistX = vec3(vUv.x, float(1.0).sub(vUv.x), float(0.0)).x;
    return baseColor;
  })();

  material.colorNode = gradientNode;

  // emissive edge: border ring based on uv distance to edge
  const edgeWidthX = uniform(float(0.015 / W));
  const edgeWidthY = uniform(float(0.015 / H));
  const emissiveNode = Fn(() => {
    const distL = vUv.x;
    const distR = float(1.0).sub(vUv.x);
    const distB = vUv.y;
    const distT = float(1.0).sub(vUv.y);
    const nearX = step(distL, edgeWidthX).add(step(distR, edgeWidthX));
    const nearY = step(distB, edgeWidthY).add(step(distT, edgeWidthY));
    const isEdge = nearX.add(nearY);
    const mask = step(float(0.5), isEdge);
    return accentColor.mul(emissiveIntensity).mul(mask);
  })();

  material.emissiveNode = emissiveNode;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  group.add(mesh);

  // contact shadow plane
  const shadowGeo = new THREE.PlaneGeometry(W * 0.9, H * 0.4);
  const shadowMat = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color('#000000'),
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -H * 0.5 - 0.08, -0.01);
  shadowMesh.rotation.x = 0;
  group.add(shadowMesh);

  // Text: label + caption
  const labelTypo = config.visual?.typography?.['cta-label'] || { fontSize: 20, fontWeight: 700, letterSpacing: 0.08 };
  const captionTypo = config.visual?.typography?.caption || { fontSize: 9, fontWeight: 400, letterSpacing: 0.12 };

  const labelText = ctx.fontAtlas.createText({
    text: 'BEGIN COMMISSION',
    font: 'JetBrains Mono',
    weight: labelTypo.fontWeight,
    fontSize: 0.14,
    letterSpacing: labelTypo.letterSpacing,
    color: config.visual?.colors?.paper || '#e8ecf2',
    align: 'center',
    anchor: 'center',
  });
  labelText.position.set(0, 0.02, 0.031);
  group.add(labelText);

  const captionText = ctx.fontAtlas.createText({
    text: 'NO DEPOSIT REQUIRED',
    font: 'JetBrains Mono',
    weight: captionTypo.fontWeight,
    fontSize: 0.06,
    letterSpacing: captionTypo.letterSpacing,
    color: config.visual?.colors?.paper || '#e8ecf2',
    align: 'center',
    anchor: 'center',
  });
  captionText.position.set(0, -H * 0.5 - 0.25, 0.001);
  group.add(captionText);

  // scene placement
  const pos = config.scenePosition?.position || [0, 0, 0];
  const rot = config.scenePosition?.rotation || [0, 0, 0];
  const scl = config.scenePosition?.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // Apply cinematic primitives (none specified, but loop for future-proofing)
  const primitiveList = config.cinematicPrimitives || [];
  primitiveList.forEach((primitive) => {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  });

  // Mount animation: weighted-settle
  const settleTl = gsap.timeline();
  group.scale.set(scl[0] * 1.04, scl[1] * 1.04, scl[2] * 1.04);
  settleTl.to(group.scale, {
    x: scl[0], y: scl[1], z: scl[2],
    duration: 0.9,
    ease: 'power4.out',
  });

  // Hover state
  let hoverTl = null;
  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
    hoverTl.to(emissiveIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
  };
  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
    hoverTl.to(emissiveIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
  };

  // Press state
  let pressTl = null;
  const onPointerDown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: scl[0] * 0.97, y: scl[1] * 0.97, z: scl[2] * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
    pressTl.to(shadowMat, { opacity: 0.5, duration: 0.12 }, 0);
  };
  const onPointerUp = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: scl[0], y: scl[1], z: scl[2],
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
    pressTl.to(shadowMat, { opacity: 0.35, duration: 0.12 }, 0);
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
  };

  group.userData.cleanup = () => {
    settleTl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (labelText.userData?.cleanup) labelText.userData.cleanup();
    if (captionText.userData?.cleanup) captionText.userData.cleanup();
    if (labelText.geometry) labelText.geometry.dispose();
    if (labelText.material) labelText.material.dispose();
    if (captionText.geometry) captionText.geometry.dispose();
    if (captionText.material) captionText.material.dispose();
  };

  return group;
}
